package com.cpf.core.common.lineage;import com.cpf.core.api.lineage.*;import java.util.*;import java.util.concurrent.locks.ReentrantLock;/** 외부 lineage backend가 없을 때 테스트/로컬에서 사용하는 bounded recorder입니다. */public final class CpfBoundedLineageRecorder implements CpfLineageRecorder {private final int capacity;private final Deque<CpfLineageRecord> records=new ArrayDeque<>();private final ReentrantLock lock=new ReentrantLock();public CpfBoundedLineageRecorder(int capacity){if(capacity<1)throw new IllegalArgumentException("capacity");this.capacity=capacity;}public void record(CpfLineageRecord r){Objects.requireNonNull(r);lock.lock();try{while(records.size()>=capacity)records.removeFirst();records.addLast(r);}finally{lock.unlock();}}public List<CpfLineageRecord> snapshot(){lock.lock();try{return List.copyOf(records);}finally{lock.unlock();}}}